BR.geschiedenissen.push(
{
  nr: 134, t: "De Heilige Geest wordt uitgestort", ref: "Handelingen 2:1–13", sectie: "gemeente",
  stappen: ["handelingen:nt-gemeente:0"], vorm: "plek",
  uitleg: "Na de hemelvaart blijven de discipelen in Jeruzalem, zoals de Heere Jezus gezegd had. Op de dag van het Pinksterfeest zijn ze allemaal eensgezind bij elkaar. Plotseling komt er uit de hemel een geluid als van een geweldige wind, en het hele huis wordt ermee gevuld. Ze zien tongen als van vuur, die zich verdelen en op ieder van hen komen. Ze worden allemaal vervuld met de Heilige Geest en spreken in andere talen. In Jeruzalem zijn Joden en Jodengenoten uit veel landen: uit Parthië en Mesopotamië, uit Egypte en Libië, uit Rome, Kreta en Arabië. Iedereen hoort de discipelen in zijn eigen taal spreken over de grote werken van God. Sommigen staan verbaasd en vragen wat dit betekent; anderen spotten dat ze dronken zijn.",
  betekenis: "De Heere Jezus had beloofd dat de Vader een andere Trooster zou sturen, de Geest der waarheid (Johannes 14:16–17). Met Pinksteren gaat die belofte in vervulling, zoals de profeet Joël al gezegd had (Joël 2:28; Handelingen 2:16–17).",
  wie: ["Petrus", "Apostelen"], kw: "heilige-geest",
  ontdek: { soort: "koppel", titel: "Wat zagen en hoorden ze met Pinksteren?", paren: [
    ["Een geluid als van een geweldige wind", "vult het hele huis waar ze zitten (2:2)"],
    ["Tongen als van vuur", "verdelen zich en komen op ieder van hen (2:3)"],
    ["Andere talen", "ieder hoort de grote werken van God in zijn eigen taal (2:6, 11)"],
    ["Spotters", "zeggen: ‘Zij zijn vol zoeten wijns’ (2:13)"]] },
  quiz: [{ q: "Op welk feest kwam de Heilige Geest?", a: ["Op het Pinksterfeest", "Op het Loofhuttenfeest", "Op het Paasfeest"], why: "Handelingen 2:1" },
    { q: "Waar leek het geluid uit de hemel op?", a: ["Op een geweldige, gedreven wind", "Op een donderslag", "Op een bazuin"], why: "Handelingen 2:2" },
    { q: "Wat zagen de discipelen op ieder van hen komen?", a: ["Tongen als van vuur", "Een duif", "Een wolk"], why: "Handelingen 2:3" },
    { q: "Wat zeiden de spotters?", a: ["Zij zijn vol zoeten wijns", "Zij zijn profeten", "Zij zijn engelen"], why: "Handelingen 2:13" }],
  cross: [["Johannes 14:16–17", "De Heere Jezus belooft een andere Trooster, de Geest der waarheid, Die bij de discipelen zal blijven."],
    ["Handelingen 1:8", "‘Gij zult ontvangen de kracht des Heiligen Geestes, Die over u komen zal.’"],
    ["Joël 2:28", "God belooft: ‘Ik Mijn Geest zal uitgieten over alle vlees.’"],
    ["Leviticus 23:15–16", "Vijftig dagen na het Pascha moest Israël een feest vieren: daarom heet het Pinksteren (‘vijftigste’)."]],
  tl: [30, 33], tijd: "ca. 30 of 33 n.Chr.", tijdNoot: "Reconstructie. Pinksteren valt vijftig dagen na het Pascha waarin de Heere Jezus gekruisigd werd. Voor die kruisiging worden vooral de jaren 30 en 33 n.Chr. verdedigd; de Bijbel noemt geen jaartal.",
},
{
  nr: 135, t: "Petrus preekt op de Pinksterdag", ref: "Handelingen 2:14–47", sectie: "gemeente",
  stappen: ["handelingen:nt-gemeente:1"], vorm: "plek",
  uitleg: "Petrus staat op met de elf andere apostelen en spreekt de menigte toe. Deze mensen zijn niet dronken, zegt hij, want het is pas het derde uur van de dag. Wat hier gebeurt, had God door de profeet Joël beloofd: Hij zou Zijn Geest uitstorten op alle vlees. Dan vertelt Petrus over Jezus van Nazareth, Die God door wonderen en tekenen had aangewezen. Hij zegt tegen de mensen: jullie hebben Hem door de handen van onrechtvaardigen aan het kruis laten slaan. Maar God heeft Hem opgewekt, zoals David al in de Psalmen schreef. Nu zit Hij aan de rechterhand van God en heeft Hij de Heilige Geest uitgestort. De mensen worden in hun hart geraakt en vragen wat ze moeten doen. ‘Bekeert u’, zegt Petrus, ‘en een iegelijk van u worde gedoopt in den Naam van Jezus Christus, tot vergeving der zonden.’ Ongeveer drieduizend mensen laten zich dopen. Ze blijven bij de leer van de apostelen, de gemeenschap, het breken van het brood en de gebeden.",
  betekenis: "Dezelfde Petrus die de Heere Jezus driemaal verloochende (Lukas 22:61–62), preekt nu vrijmoedig over Zijn opstanding. Petrus zegt erbij: ‘u komt de belofte toe, en uw kinderen, en allen, die daar verre zijn, zo velen als er de Heere, onze God, toe roepen zal’ (Handelingen 2:39).",
  wie: ["Petrus", "Apostelen"],
  ontdek: { soort: "wiezei", titel: "Wie zei het?", items: [
    ["Zij zijn vol zoeten wijns.", "Spotters in de menigte", ["Petrus", "De profeet Joël"]],
    ["Ik zal uitstorten van Mijn Geest op alle vlees.", "God, door de profeet Joël", ["Petrus", "Mozes"]],
    ["Wat zullen wij doen, mannen broeders?", "De mensen die in hun hart geraakt waren", ["De apostelen", "De spotters"]],
    ["Bekeert u, en een iegelijk van u worde gedoopt in den Naam van Jezus Christus.", "Petrus", ["Johannes de Doper", "David"]]] },
  quiz: [{ q: "Hoe laat was het volgens Petrus toen de Geest kwam?", a: ["Het derde uur van de dag", "Middernacht", "Het negende uur"], why: "Handelingen 2:15" },
    { q: "Welke profeet haalde Petrus aan over het uitstorten van de Geest?", a: ["Joël", "Jona", "Maleachi"], why: "Handelingen 2:16" },
    { q: "Welke koning noemde Petrus, die ‘gestorven en begraven is’?", a: ["David", "Salomo", "Saul"], why: "Handelingen 2:29" },
    { q: "Waarin bleven de gelovigen volharden?", a: ["In de leer der apostelen, de gemeenschap, de breking des broods en de gebeden", "In vasten en offeren", "In reizen naar andere landen"], why: "Handelingen 2:42" }],
  cross: [["Psalm 16:10", "‘Gij zult niet toelaten, dat Uw Heilige de verderving zie.’ Petrus zegt dat David hier over de opstanding van Christus sprak."],
    ["Psalm 110:1", "‘Zit aan Mijn rechterhand.’ Petrus haalt dit aan: niet David, maar Christus is opgevaren."],
    ["Joël 2:32", "‘Al wie den Naam des HEEREN zal aanroepen, zal behouden worden.’"],
    ["Lukas 22:61–62", "Petrus had de Heere Jezus verloochend en bitter gehuild; nu getuigt hij vrijmoedig van Hem."]],
  tl: [30, 33], tijd: "ca. 30 of 33 n.Chr.", tijdNoot: "Reconstructie: dezelfde dag als de uitstorting van de Heilige Geest (Handelingen 2:1, 41). Voor het jaar worden vooral 30 en 33 n.Chr. verdedigd.",
},
{
  nr: 136, t: "De kreupele bij de Schone Poort en meer genezingen", ref: "Handelingen 3:1–4:22; 5:12–42", sectie: "gemeente",
  stappen: ["handelingen:nt-gemeente:2", "handelingen:nt-gemeente:4"], vorm: "plek",
  uitleg: "Petrus en Johannes gaan om het negende uur naar de tempel om te bidden. Bij de Schone Poort zit een man die vanaf zijn geboorte kreupel is. Hij vraagt om geld, maar Petrus zegt: ‘Zilver en goud heb ik niet, maar hetgeen ik heb, dat geve ik u; in den Naam van Jezus Christus, den Nazarener, sta op en wandel!’ De man springt op en loopt met hen de tempel in, God lovend. Petrus zegt tegen het verbaasde volk dat niet hun eigen kracht hem gezond maakte, maar het geloof in de Naam van Jezus. Petrus en Johannes worden gevangengezet en voor de raad gebracht. Maar ze zeggen: ‘wij kunnen niet laten te spreken, hetgeen wij gezien en gehoord hebben.’ Later gebeuren er nog meer wonderen. Zieken worden langs de straat gelegd, zodat de schaduw van Petrus op hen valt, en ze worden allemaal genezen. De apostelen worden weer gevangengezet, maar een engel opent ’s nachts de deuren. De volgende morgen gaan ze in de tempel verder met preken.",
  betekenis: "De apostelen genazen niet in eigen kracht, maar in de Naam van Jezus Christus (Handelingen 3:12, 16). Petrus zegt het voor de raad zo: ‘er is ook onder den hemel geen andere Naam, Die onder de mensen gegeven is, door Welken wij moeten zalig worden’ (Handelingen 4:12).",
  wie: ["Petrus", "Johannes", "Gamaliël"],
  ontdek: { soort: "onthul", titel: "Tik op een plek of een moment", items: [
    ["De Schone Poort", "Een poort van de tempel. Daar zat de kreupele man elke dag om een aalmoes te vragen (3:2)."],
    ["Salomo's voorhof", "Een zuilengang bij de tempel. Daar liep het volk naartoe na de genezing, en daar kwamen de gelovigen samen (3:11; 5:12)."],
    ["Voor de raad", "Petrus en Johannes moeten zich verantwoorden. De raad ziet hun vrijmoedigheid en de genezen man naast hen staan (4:13–14)."],
    ["De schaduw van Petrus", "Zieken worden langs de straat gelegd, zodat als Petrus voorbijkomt ten minste zijn schaduw op hen valt (5:15)."],
    ["De engel bij de gevangenis", "Een engel van de Heere opent ’s nachts de deuren: ‘spreekt in den tempel tot het volk al de woorden dezes levens’ (5:19–20)."]] },
  quiz: [{ q: "Hoe heette de poort waar de kreupele man zat?", a: ["De Schone", "De Schaapspoort", "De Vispoort"], why: "Handelingen 3:2" },
    { q: "Hoe oud was de man die genezen werd?", a: ["Meer dan veertig jaar", "Twaalf jaar", "Zeventig jaar"], why: "Handelingen 4:22" },
    { q: "Wat zeiden Petrus en Johannes tegen de raad?", a: ["Wij kunnen niet laten te spreken, hetgeen wij gezien en gehoord hebben", "Wij zullen voortaan zwijgen", "Wij gaan terug naar Galilea"], why: "Handelingen 4:20" },
    { q: "Wie opende ’s nachts de deuren van de gevangenis?", a: ["Een engel des Heeren", "De hogepriester", "Gamaliël"], why: "Handelingen 5:19" }],
  cross: [["Jesaja 35:6", "‘Alsdan zal de kreupele springen als een hert.’"],
    ["Psalm 118:22", "‘De steen, dien de bouwlieden verworpen hadden, is tot een hoofd des hoeks geworden.’ Petrus past dit voor de raad toe op Christus (Handelingen 4:11)."],
    ["Handelingen 4:12", "‘Er is ook onder den hemel geen andere Naam, Die onder de mensen gegeven is, door Welken wij moeten zalig worden.’"]],
  tl: [30, 34], tijd: "ca. 30–34 n.Chr.", tijdNoot: "Reconstructie: kort na Pinksteren. De Bijbel noemt geen jaartal; afhankelijk van het jaar van de kruisiging (30 of 33) valt dit in de eerste jaren daarna.",
},
{
  nr: 137, t: "Ananias en Saffira", ref: "Handelingen 4:32–5:11", sectie: "gemeente",
  stappen: ["handelingen:nt-gemeente:3"], vorm: "plek",
  uitleg: "In de eerste gemeente zijn de gelovigen één van hart en ziel. Wie land of een huis heeft, verkoopt het soms en legt het geld aan de voeten van de apostelen. Dan wordt er uitgedeeld aan wie iets nodig heeft. Barnabas, een Leviet uit Cyprus, verkoopt zo een akker. Ook Ananias en zijn vrouw Saffira verkopen een stuk land. Maar Ananias houdt een deel van het geld achter, en zijn vrouw weet ervan. De rest legt hij aan de voeten van de apostelen, alsof het alles is. Petrus zegt: ‘Ananias, waarom heeft de satan uw hart vervuld, dat gij den Heiligen Geest liegen zoudt?’ Het land was van hem, en ook het geld: ‘Gij hebt den mensen niet gelogen, maar Gode.’ Ananias valt neer en sterft, en jonge mannen dragen hem weg en begraven hem. Ongeveer drie uur later komt Saffira binnen, die niet weet wat er gebeurd is. Ook zij liegt over de prijs, valt neer en sterft. Grote vrees komt over de hele gemeente.",
  betekenis: "God ziet het hart en laat Zich niet bespotten (Galaten 6:7). Liegen tegen de Heilige Geest is liegen tegen God (Handelingen 5:3–4).",
  wie: ["Ananias", "Saffira", "Petrus", "Barnabas"],
  ontdek: { soort: "volgorde", titel: "Zet het verhaal in de goede volgorde", items: [
    "Ze verkopen een stuk land", "Ze houden een deel van het geld achter", "Ananias legt de rest aan de voeten van de apostelen",
    "Ananias valt dood neer", "Drie uur later komt Saffira", "Ook Saffira sterft"] },
  quiz: [{ q: "Wie verkocht een akker en gaf het hele bedrag aan de apostelen?", a: ["Barnabas", "Ananias", "Simon"], why: "Handelingen 4:36–37" },
    { q: "Tegen Wie had Ananias volgens Petrus gelogen?", a: ["Tegen God", "Alleen tegen de apostelen", "Tegen zijn vrouw"], why: "Handelingen 5:4" },
    { q: "Hoeveel tijd later kwam Saffira binnen?", a: ["Ongeveer drie uur", "Drie dagen", "Een week"], why: "Handelingen 5:7" },
    { q: "Wat kwam er na deze gebeurtenis over de gemeente?", a: ["Grote vreze", "Grote honger", "Een aardbeving"], why: "Handelingen 5:11" }],
  cross: [["Jozua 7:21", "Achan nam in het geheim zilver en goud en verborg het in zijn tent. Ook daar wilde iemand voor God verbergen wat hij had gedaan."],
    ["Spreuken 12:22", "‘Valse lippen zijn den HEERE een gruwel; maar die trouwelijk handelen, zijn Zijn welgevallen.’"],
    ["Galaten 6:7", "‘God laat Zich niet bespotten; want zo wat de mens zaait, dat zal hij ook maaien.’"]],
  tl: [30, 35], tijd: "ca. 30–35 n.Chr.", tijdNoot: "Reconstructie: in de eerste jaren van de gemeente in Jeruzalem, vóór de dood van Stefanus. De Bijbel noemt geen jaartal.",
},
{
  nr: 138, t: "Stefanus, de eerste die om de Heere Jezus gedood wordt", ref: "Handelingen 6:1–8:3", sectie: "gemeente",
  stappen: ["handelingen:nt-gemeente:5", "handelingen:nt-gemeente:6"], vorm: "plek",
  uitleg: "De gemeente in Jeruzalem kiest zeven mannen om voor de weduwen te zorgen. Een van hen is Stefanus, een man vol geloof en van de Heilige Geest. Hij doet grote wonderen en tekenen onder het volk. Sommigen gaan met hem in discussie, maar ze kunnen niet op tegen de wijsheid en de Geest waarmee hij spreekt. Dan zoeken ze valse getuigen, die zeggen dat hij lastert tegen Mozes, de wet en de tempel. Ze brengen hem voor de raad. Stefanus vertelt de geschiedenis van Abraham, Jozef, Mozes en David. Hij zegt dat Israël de Heilige Geest altijd weerstaan heeft, net als hun vaders. Dan ziet hij de hemel geopend en de Heere Jezus staan aan de rechterhand van God. Ze stoppen hun oren dicht, werpen hem de stad uit en stenigen hem. De getuigen leggen hun kleren aan de voeten van Saulus. Stefanus bidt: ‘Heere Jezus, ontvang mijn geest.’ Op zijn knieën roept hij: ‘Heere, reken hun deze zonde niet toe!’ Godvrezende mannen begraven hem met grote rouw.",
  betekenis: "Stefanus vergeeft zijn vijanden, zoals de Heere Jezus aan het kruis bad: ‘Vader, vergeef het hun’ (Lukas 23:34). De Heere Jezus had gezegd: ‘bidt voor degenen, die u geweld doen, en die u vervolgen’ (Mattheüs 5:44).",
  wie: ["Stefanus", "Saulus", "Apostelen"], kw: "vergeving",
  ontdek: { soort: "verbanden", titel: "Stefanus en zijn Heere", items: [
    ["Lukas 23:34", "De Heere Jezus bidt aan het kruis: ‘Vader, vergeef het hun.’", "Handelingen 7:60", "Stefanus bidt: ‘Heere, reken hun deze zonde niet toe!’"],
    ["Lukas 23:46", "‘Vader, in Uw handen beveel Ik Mijn geest.’", "Handelingen 7:59", "‘Heere Jezus, ontvang mijn geest.’"],
    ["Lukas 22:69", "‘Van nu aan zal de Zoon des mensen gezeten zijn aan de rechter hand der kracht Gods.’", "Handelingen 7:56", "Stefanus ziet ‘den Zoon des mensen, staande ter rechter hand Gods’."]] },
  quiz: [{ q: "Waarom werden er zeven mannen gekozen?", a: ["Omdat weduwen vergeten werden bij het dagelijkse uitdelen", "Om de tempel te bewaken", "Om naar Rome te reizen"], why: "Handelingen 6:1–3" },
    { q: "Hoe zag het gezicht van Stefanus eruit voor de raad?", a: ["Als het aangezicht van een engel", "Rood van woede", "Bedroefd en bang"], why: "Handelingen 6:15" },
    { q: "Wat zag Stefanus toen hij naar de hemel keek?", a: ["De heerlijkheid van God en Jezus aan Gods rechterhand", "Een ladder met engelen", "Een vurige wagen"], why: "Handelingen 7:55" },
    { q: "Wat bad Stefanus vlak voor hij stierf?", a: ["Heere, reken hun deze zonde niet toe!", "Heere, straf hen!", "Heere, red mij van deze mensen!"], why: "Handelingen 7:60" }],
  cross: [["Lukas 23:34", "‘Vader, vergeef het hun; want zij weten niet, wat zij doen.’"],
    ["Mattheüs 5:44", "‘Hebt uw vijanden lief … bidt voor degenen, die u geweld doen, en die u vervolgen.’"],
    ["Handelingen 22:20", "Jaren later vertelt Paulus zelf dat hij erbij stond toen het bloed van Stefanus vergoten werd, en de kleren bewaarde."]],
  tl: [31, 35], tijd: "ca. 31–35 n.Chr.", tijdNoot: "Reconstructie: na de eerste jaren van de gemeente en vóór de bekering van Saulus (ca. 33–36 n.Chr.). De Bijbel noemt geen jaartal.",
},
{
  nr: 139, t: "Filippus in Samaria en de kamerling uit Ethiopië", ref: "Handelingen 8:4–40", sectie: "gemeente",
  stappen: ["handelingen:nt-gemeente:7", "handelingen:nt-gemeente:8"], vorm: "route",
  uitleg: "Na de dood van Stefanus worden de gelovigen verstrooid, en overal waar ze komen verkondigen ze het Woord. Filippus, een van de zeven, gaat naar de stad van Samaria en predikt daar Christus. Er gebeuren tekenen, en er is grote blijdschap in die stad. Zelfs de tovenaar Simon laat zich dopen, maar later wil hij de gave van God met geld kopen. Dan zegt een engel van de Heere tegen Filippus dat hij naar de weg van Jeruzalem naar Gaza moet gaan. Daar rijdt een kamerling uit Ethiopië op zijn wagen. Hij had in Jeruzalem aangebeden en leest nu de profeet Jesaja: ‘Hij is gelijk een schaap ter slachting geleid.’ Filippus vraagt of hij begrijpt wat hij leest. Dan begint hij bij die Schrift en verkondigt hem Jezus. Bij water vraagt de kamerling wat hem verhindert gedoopt te worden. Hij zegt: ‘Ik geloof, dat Jezus Christus de Zoon van God is’, en hij wordt gedoopt. Daarna neemt de Geest van de Heere Filippus weg, en de kamerling reist met blijdschap verder.",
  betekenis: "Het Evangelie gaat verder, precies zoals de Heere Jezus gezegd had: Jeruzalem, Judea, Samaria en tot aan het uiterste der aarde (Handelingen 1:8). De kamerling leert dat Jesaja 53 over de Heere Jezus gaat (Handelingen 8:35).",
  wie: ["Filippus de evangelist", "Simon de tovenaar", "Petrus", "Johannes", "Kamerling"],
  ontdek: { soort: "kaart", titel: "Waar ging de weg naartoe?", vraag: "Tik op de stad waar de weg naartoe liep waarop Filippus de kamerling ontmoette.", id: "gaza", v: "kanaan" },
  quiz: [{ q: "Wat wilde Simon de tovenaar kopen?", a: ["De macht om de Heilige Geest te geven", "Een stuk land", "De wagen van de kamerling"], why: "Handelingen 8:18–19" },
    { q: "Waar las de kamerling uit?", a: ["Uit de profeet Jesaja", "Uit de Psalmen", "Uit Genesis"], why: "Handelingen 8:30" },
    { q: "Wat vroeg Filippus aan de kamerling?", a: ["Verstaat gij ook, hetgeen gij leest?", "Waar gaat u naartoe?", "Mag ik meerijden?"], why: "Handelingen 8:30" },
    { q: "Waar werd Filippus gevonden nadat de Geest hem had weggenomen?", a: ["In Azote", "In Gaza", "In Jeruzalem"], why: "Handelingen 8:40" }],
  cross: [["Jesaja 53:7", "‘Als een lam werd Hij ter slachting geleid … alzo deed Hij Zijn mond niet open.’ Dit las de kamerling."],
    ["Handelingen 1:8", "‘Zo te Jeruzalem, als in geheel Judea en Samaria, en tot aan het uiterste der aarde.’"],
    ["Psalm 68:32", "‘Morenland zal zich haasten zijn handen tot God uit te strekken.’"],
    ["Handelingen 21:8", "Jaren later woont Filippus in Caesarea, en Paulus logeert bij hem."]],
  tl: [32, 36], tijd: "ca. 32–36 n.Chr.", tijdNoot: "Reconstructie: kort na de dood van Stefanus (Handelingen 8:1–4). De Bijbel noemt geen jaartal.",
},
{
  nr: 140, t: "Tabitha wordt weer levend", ref: "Handelingen 9:32–43", sectie: "gemeente",
  stappen: ["handelingen:nt-gemeente:9", "handelingen:nt-gemeente:10"], vorm: "route",
  uitleg: "Petrus reist rond langs de gemeenten en komt in Lydda, waar hij de verlamde Eneas geneest. Vlakbij, in de havenstad Joppe, woont een discipelin die Tabitha heet, in het Grieks Dorkas. Ze is vol goede werken en aalmoezen; ze maakt rokken en kleren voor de weduwen. Dan wordt ze ziek en sterft. De discipelen wassen haar en leggen haar in de bovenkamer. Ze sturen twee mannen naar Petrus: kom zonder uitstel. Als Petrus komt, staan alle weduwen te huilen. Ze laten de kleren zien die Dorkas gemaakt had toen ze nog bij hen was. Petrus stuurt iedereen naar buiten, knielt neer, bidt en zegt: ‘Tabitha, sta op!’ Ze doet haar ogen open en gaat overeind zitten. Petrus laat haar levend aan de gelovigen en weduwen zien. In heel Joppe wordt het bekend, en velen gaan in de Heere geloven.",
  betekenis: "Tabitha diende de Heere door voor weduwen te zorgen; de Bijbel noemt haar ‘vol van goede werken’ (Handelingen 9:36). De Heere Jezus zei: ‘Voor zoveel gij dit een van deze Mijn minste broeders gedaan hebt, zo hebt gij dat Mij gedaan’ (Mattheüs 25:40).",
  wie: ["Tabitha", "Petrus", "Eneas", "Weduwen"], kw: "dienen",
  ontdek: { soort: "onthul", titel: "Tik op wat er in Joppe te zien was", items: [
    ["Vol goede werken", "Tabitha deed veel goed en gaf veel aalmoezen (9:36)."],
    ["De bovenkamer", "Daar legden ze haar neer nadat ze haar gewassen hadden (9:37)."],
    ["Twee mannen", "Zij werden naar Lydda gestuurd om Petrus te halen (9:38)."],
    ["Rokken en kleren", "De weduwen lieten zien wat Dorkas voor hen gemaakt had (9:39)."],
    ["Simon de leerlooier", "Bij hem bleef Petrus daarna vele dagen in Joppe (9:43)."]] },
  quiz: [{ q: "Hoe lang lag Eneas al verlamd op bed?", a: ["Acht jaar", "Achttien jaar", "Drie jaar"], why: "Handelingen 9:33" },
    { q: "Wat is de Griekse naam van Tabitha?", a: ["Dorkas", "Rhode", "Lydia"], why: "Handelingen 9:36" },
    { q: "Wat deed Petrus voordat hij zei: ‘Tabitha, sta op!’?", a: ["Hij knielde neer en bad", "Hij zalfde haar met olie", "Hij las uit de Schriften"], why: "Handelingen 9:40" },
    { q: "Bij wie bleef Petrus daarna in Joppe?", a: ["Bij Simon, een lederbereider", "Bij Cornelius", "Bij Filippus"], why: "Handelingen 9:43" }],
  cross: [["Markus 5:41", "Petrus was erbij toen de Heere Jezus het dochtertje van Jaïrus opwekte: ‘Talitha kumi!’ (zie ook Markus 5:37)."],
    ["1 Koningen 17:22", "Ook in het Oude Testament wekte God een kind weer op, na het gebed van Elia."],
    ["Mattheüs 25:40", "‘Voor zoveel gij dit een van deze Mijn minste broeders gedaan hebt, zo hebt gij dat Mij gedaan.’"],
    ["Jakobus 1:27", "‘Wezen en weduwen bezoeken in hun verdrukking’ is volgens Jakobus zuivere godsdienst."]],
  tl: [35, 40], tijd: "ca. 35–40 n.Chr.", tijdNoot: "Reconstructie: na de bekering van Saulus, in een tijd van rust voor de gemeenten (Handelingen 9:31). De Bijbel noemt geen jaartal.",
},
{
  nr: 141, t: "Cornelius, een Romeinse hoofdman", ref: "Handelingen 10:1–11:18", sectie: "gemeente",
  stappen: ["handelingen:nt-gemeente:11", "handelingen:nt-gemeente:12"], vorm: "route",
  uitleg: "In Caesarea woont Cornelius, een hoofdman over honderd in het Romeinse leger. Hij vreest God met zijn hele huis, geeft veel aalmoezen en bidt veel. Een engel zegt hem dat hij Simon Petrus uit Joppe moet laten halen. De volgende dag ziet Petrus op het dak in Joppe een groot laken uit de hemel neerdalen, vol dieren die een Jood niet mocht eten. Een stem zegt: ‘Sta op, Petrus! slacht en eet.’ Als hij weigert, zegt de stem: ‘Hetgeen God gereinigd heeft, zult gij niet gemeen maken.’ Op dat moment komen de mannen van Cornelius, en de Geest zegt Petrus dat hij met hen moet meegaan. In Caesarea vertelt Petrus aan Cornelius en zijn familie en vrienden over Jezus. Ieder die in Hem gelooft, ontvangt vergeving van de zonden. Terwijl Petrus nog spreekt, valt de Heilige Geest op allen die luisteren, en ze worden gedoopt. In Jeruzalem horen de broeders het verhaal van Petrus. Ze zeggen: ‘Zo heeft dan God ook den heidenen de bekering gegeven ten leven!’",
  betekenis: "God had aan Abraham beloofd dat in hem alle geslachten van de aarde gezegend zouden worden (Genesis 12:3). Petrus leert in Caesarea ‘dat God geen aannemer des persoons is’ (Handelingen 10:34): ook heidenen worden behouden door het geloof (Handelingen 15:9).",
  wie: ["Cornelius", "Petrus", "Boden", "Broeders"],
  ontdek: { soort: "wiezei", titel: "Wie zei het?", items: [
    ["Uw gebeden en uw aalmoezen zijn tot gedachtenis opgekomen voor God.", "De engel tegen Cornelius", ["Petrus", "Simon de leerlooier"]],
    ["Geenszins, Heere! want ik heb nooit gegeten iets, dat gemeen of onrein was.", "Petrus", ["Cornelius", "Een knecht van Cornelius"]],
    ["Sta op, ik ben ook zelf een mens.", "Petrus tegen Cornelius", ["De engel", "Cornelius tegen zijn knecht"]],
    ["Zo heeft dan God ook den heidenen de bekering gegeven ten leven!", "De gelovigen in Jeruzalem", ["Cornelius", "De engel"]]] },
  quiz: [{ q: "Over hoeveel soldaten was Cornelius hoofdman?", a: ["Over honderd", "Over duizend", "Over tien"], why: "Handelingen 10:1" },
    { q: "Waarom klom Petrus op het dak?", a: ["Om te bidden", "Om te slapen", "Om naar de zee te kijken"], why: "Handelingen 10:9" },
    { q: "Hoe vaak zag Petrus het laken neerdalen?", a: ["Drie keer", "Eén keer", "Zeven keer"], why: "Handelingen 10:16" },
    { q: "Wat gebeurde er terwijl Petrus nog sprak in het huis van Cornelius?", a: ["De Heilige Geest viel op allen die het Woord hoorden", "Het huis begon te schudden", "Er verscheen een engel"], why: "Handelingen 10:44" }],
  cross: [["Genesis 12:3", "‘In u zullen alle geslachten des aardrijks gezegend worden.’"],
    ["Jona 1:3", "Ook Jona vertrok uit Joppe (Jafo), maar hij vluchtte weg van Gods opdracht aan de heidenen."],
    ["Handelingen 15:7–9", "Petrus herinnert de apostelen eraan dat God geen onderscheid maakte, maar ook de harten van de heidenen reinigde door het geloof."]],
  tl: [37, 41], tijd: "ca. 37–41 n.Chr.", tijdNoot: "Reconstructie: na de reis van Petrus langs Lydda en Joppe en vóór de dood van Herodes (44 n.Chr.). De Bijbel noemt geen jaartal.",
},
{
  nr: 142, t: "Petrus bevrijd uit de gevangenis", ref: "Handelingen 12:1–25", sectie: "gemeente",
  stappen: ["handelingen:nt-gemeente:13", "handelingen:nt-gemeente:14"], vorm: "plek",
  uitleg: "Koning Herodes laat Jakobus, de broer van Johannes, met het zwaard doden. Omdat de Joden daar blij mee zijn, laat hij ook Petrus gevangennemen, in de dagen van de ongezuurde broden. Zestien soldaten in vier wachten moeten hem bewaken. Ondertussen bidt de gemeente onophoudelijk tot God voor hem. In de laatste nacht slaapt Petrus tussen twee soldaten, gebonden met twee kettingen. Dan staat er een engel van de Heere, en licht schijnt in de cel. De kettingen vallen af, en de engel leidt hem langs twee wachten naar de ijzeren poort, die vanzelf opengaat. Petrus denkt eerst dat hij droomt. Maar buiten zegt hij: nu weet ik zeker dat de Heere Zijn engel gestuurd heeft. Hij klopt aan bij het huis van Maria, de moeder van Johannes Markus, waar velen bidden. Rhode hoort zijn stem, maar doet van blijdschap de deur niet open. Later laat Herodes zich in Caesarea als een god toejuichen. Een engel van de Heere slaat hem, omdat hij God de eer niet geeft, en hij sterft. Maar het Woord van God groeit en vermenigvuldigt zich.",
  betekenis: "De gemeente bidt, en God verhoort op een manier die ze zelf nauwelijks kunnen geloven (Handelingen 12:5, 15–16). ‘De Engel des HEEREN legert Zich rondom degenen, die Hem vrezen, en rukt hen uit’ (Psalm 34:8).",
  wie: ["Herodes (Agrippa I)", "Petrus", "Rhode"],
  ontdek: { soort: "volgorde", titel: "Zet de nacht van de bevrijding in de goede volgorde", items: [
    "Jakobus wordt gedood", "Petrus wordt gevangengezet", "De gemeente bidt voor hem", "Een engel wekt Petrus",
    "De ijzeren poort gaat vanzelf open", "Rhode hoort Petrus kloppen"] },
  quiz: [{ q: "Wie liet koning Herodes met het zwaard doden?", a: ["Jakobus, de broer van Johannes", "Stefanus", "Filippus"], why: "Handelingen 12:2" },
    { q: "Hoeveel kettingen had Petrus om in de gevangenis?", a: ["Twee", "Eén", "Zeven"], why: "Handelingen 12:6" },
    { q: "Waar ging Petrus naartoe na zijn bevrijding?", a: ["Naar het huis van Maria, de moeder van Johannes Markus", "Naar de tempel", "Naar Joppe"], why: "Handelingen 12:12" },
    { q: "Wat zeiden de biddende mensen eerst toen Rhode vertelde dat Petrus voor de deur stond?", a: ["Gij raast", "Doe snel open", "Dat wisten wij al"], why: "Handelingen 12:15" },
    { q: "Waarom sloeg een engel van de Heere koning Herodes?", a: ["Omdat hij Gode de eer niet gaf", "Omdat hij Petrus vrijliet", "Omdat hij naar Tyrus ging"], why: "Handelingen 12:23" }],
  cross: [["Psalm 34:8", "‘De Engel des HEEREN legert Zich rondom degenen, die Hem vrezen, en rukt hen uit.’"],
    ["Jakobus 5:16", "‘Een krachtig gebed des rechtvaardigen vermag veel.’"],
    ["Mattheüs 20:23", "De Heere Jezus had tegen Jakobus en Johannes gezegd: ‘Mijn drinkbeker zult gij wel drinken.’ Jakobus stierf als eerste van de apostelen om Christus."],
    ["Hebreeën 1:14", "Engelen zijn ‘gedienstige geesten, die tot dienst uitgezonden worden’."]],
  tl: [43, 44], tijd: "ca. 43–44 n.Chr.", tijdNoot: "Reconstructie. Herodes Agrippa I stierf volgens de geschiedschrijver Josephus in 44 n.Chr.; de gevangenneming van Petrus was rond een Pascha kort daarvoor (Handelingen 12:3–4, 19–23).",
},
{
  nr: 143, t: "Saulus op weg naar Damascus", ref: "Handelingen 9:1–25", sectie: "paulus",
  stappen: ["handelingen:nt-paulus:0", "handelingen:nt-paulus:1"], vorm: "route",
  uitleg: "Saulus vervolgt de gemeente en sleept mannen en vrouwen naar de gevangenis. Met brieven van de hogepriester reist hij naar Damascus, om ook daar gelovigen gevangen te nemen. Vlak bij de stad straalt plotseling een licht uit de hemel om hem heen. Hij valt op de grond en hoort: ‘Saul, Saul! wat vervolgt gij Mij?’ ‘Wie zijt Gij, Heere?’ ‘Ik ben Jezus, Dien gij vervolgt.’ Blind wordt hij Damascus binnengeleid, en drie dagen eet en drinkt hij niets. De Heere stuurt de discipel Ananias naar hem toe: ‘want zie, hij bidt.’ Ananias is bang. Maar de Heere zegt dat Saulus een uitverkoren vat is om Zijn Naam te dragen voor de heidenen, de koningen en Israël. Ananias legt hem de handen op, er vallen als schubben van zijn ogen, en Saulus wordt gedoopt. Direct predikt hij in de synagogen dat Jezus de Zoon van God is. Als men hem wil doden, laten de discipelen hem ’s nachts in een mand langs de muur zakken.",
  betekenis: "De grootste vervolger wordt door Gods genade een apostel. Paulus schreef later: ‘Christus Jezus in de wereld gekomen is, om de zondaren zalig te maken, van welke ik de voornaamste ben’ (1 Timotheüs 1:15).",
  wie: ["Saulus", "Ananias van Damascus"], kw: "bekering",
  ontdek: { soort: "onthul", titel: "Saulus: vóór en na", items: [
    ["Vóór: bij Stefanus", "De getuigen leggen hun kleren aan de voeten van Saulus, en hij heeft een welbehagen aan de dood van Stefanus (7:58; 8:1)."],
    ["Vóór: brieven voor Damascus", "Hij wil gelovigen gebonden naar Jeruzalem brengen (9:1–2)."],
    ["Op de weg", "Een licht uit de hemel en de stem van de Heere Jezus (9:3–5)."],
    ["Drie dagen", "Hij ziet niet, eet niet en drinkt niet, en hij bidt (9:9, 11)."],
    ["Na: prediker", "Hij predikt in de synagogen ‘dat Hij de Zoon van God is’ (9:20)."]] },
  quiz: [{ q: "Wat vroeg Saulus aan de hogepriester?", a: ["Brieven naar de synagogen in Damascus", "Geld voor de reis", "Soldaten om hem te beschermen"], why: "Handelingen 9:2" },
    { q: "Wat zagen de reisgenoten van Saulus?", a: ["Niemand; ze hoorden alleen de stem", "Een engel", "Een vuurkolom"], why: "Handelingen 9:7" },
    { q: "In welke straat in Damascus logeerde Saulus?", a: ["De straat die de Rechte heet", "De Koningsweg", "De Tempelstraat"], why: "Handelingen 9:11" },
    { q: "Wat viel er van de ogen van Saulus toen Ananias hem de handen oplegde?", a: ["Iets als schellen (schubben)", "Tranen", "Stof"], why: "Handelingen 9:18" }],
  cross: [["Handelingen 22:6–16", "Paulus vertelt zijn bekering zelf aan het volk in Jeruzalem."],
    ["Galaten 1:13–16", "Paulus schrijft hoe hij de gemeente vervolgde, en hoe God hem riep door Zijn genade."],
    ["1 Timotheüs 1:13–15", "‘Die te voren een gods lasteraar was, en een vervolger … maar mij is barmhartigheid geschied.’"],
    ["Filippenzen 3:5–6", "Paulus noemt zichzelf een Farizeeër, ‘naar den ijver een vervolger der Gemeente’."]],
  tl: [33, 36], tijd: "ca. 33–36 n.Chr.", tijdNoot: "Reconstructie: kort na de dood van Stefanus. Paulus schrijft dat hij ‘na drie jaren’ weer in Jeruzalem kwam (Galaten 1:18); met de latere reizen geeft dat meestal ca. 33–36 n.Chr. Andere dateringen liggen iets eerder of later.",
},
{
  nr: 144, t: "Paulus en Barnabas op reis", ref: "Handelingen 9:26–30; 11:19–30; 13–14", sectie: "paulus",
  stappen: ["handelingen:nt-paulus:2", "handelingen:nt-paulus:3", "handelingen:nt-paulus:4", "handelingen:nt-paulus:5", "handelingen:nt-paulus:6", "handelingen:nt-paulus:7"], vorm: "route",
  uitleg: "In Jeruzalem zijn de discipelen eerst bang voor Saulus, maar Barnabas neemt hem mee naar de apostelen. Daarna gaat Saulus naar Tarsus, tot Barnabas hem ophaalt naar Antiochië. Daar worden de discipelen voor het eerst christenen genoemd. In Antiochië zegt de Heilige Geest: ‘Zondert Mij af beiden Barnabas en Saulus tot het werk, waartoe Ik hen geroepen heb.’ Ze varen naar Cyprus en trekken het eiland door. In Pafos wordt de tovenaar Elymas blind, en de stadhouder gaat geloven. In Antiochië in Pisidië preekt Paulus in de synagoge over Jezus, de Zaligmaker uit het nageslacht van David. Veel heidenen zijn blij, maar er komt vervolging, ook in Ikonium. In Lystra geneest Paulus een man die nog nooit gelopen had. De mensen willen hun als goden offers brengen, maar even later wordt Paulus gestenigd. Toch keren ze terug langs dezelfde steden om de gelovigen te versterken en ouderlingen te kiezen. In Antiochië vertellen ze dat God voor de heidenen de deur van het geloof had geopend.",
  betekenis: "Paulus en Barnabas zeggen: ‘wij door vele verdrukkingen moeten ingaan in het Koninkrijk Gods’ (Handelingen 14:22). Paulus herinnert Timotheüs later aan die vervolgingen, en schrijft: ‘de Heere heeft mij uit alle verlost’ (2 Timotheüs 3:11).",
  wie: ["Paulus", "Barnabas", "Johannes Markus", "Sergius Paulus", "Elymas"],
  ontdek: { soort: "volgorde", titel: "De eerste reis: zet de plaatsen op volgorde", items: [
    "Antiochië", "Seleucië", "Salamis", "Pafos", "Perge", "Antiochië in Pisidië", "Ikonium", "Lystra", "Derbe"] },
  quiz: [{ q: "Wie bracht Saulus in Jeruzalem bij de apostelen?", a: ["Barnabas", "Ananias", "Filippus"], why: "Handelingen 9:27" },
    { q: "Wie ging bij Perge bij Paulus en Barnabas weg?", a: ["Johannes (Markus)", "Silas", "Timotheüs"], why: "Handelingen 13:13" },
    { q: "Wat deden de apostelen toen de mensen in Lystra hun wilden offeren?", a: ["Ze scheurden hun klederen", "Ze namen de offers aan", "Ze vluchtten de stad uit"], why: "Handelingen 14:14" },
    { q: "Wat kozen Paulus en Barnabas in elke gemeente op de terugweg?", a: ["Ouderlingen", "Een koning", "Twaalf apostelen"], why: "Handelingen 14:23" }],
  cross: [["Jesaja 49:6", "‘Ik heb U ook gegeven tot een Licht der heidenen.’ Paulus en Barnabas halen dit aan in Antiochië in Pisidië (Handelingen 13:47)."],
    ["Handelingen 4:36", "Barnabas betekent ‘zoon der vertroosting’; hij was een Leviet van Cyprus."],
    ["2 Timotheüs 3:11", "Paulus noemt de vervolgingen ‘in Antiochië, in Ikonium en in Lystre’."],
    ["2 Korinthe 11:25", "‘Eens ben ik gestenigd.’"]],
  tl: [46, 48], tijd: "ca. 46–48 n.Chr. (de eerste reis)", tijdNoot: "Reconstructie. Saulus kwam ca. 36 n.Chr. in Jeruzalem en Antiochië kreeg hulp tijdens de hongersnood onder keizer Claudius (Handelingen 11:28). De eerste zendingsreis (Handelingen 13–14) wordt meestal ca. 46–48 n.Chr. gedateerd. De Bijbel noemt geen jaartallen.",
},
{
  nr: 145, t: "Paulus gaat naar Filippi", ref: "Handelingen 15:36–16:40", sectie: "paulus",
  stappen: ["handelingen:nt-paulus:8", "handelingen:nt-paulus:9", "handelingen:nt-paulus:10"], vorm: "route",
  uitleg: "Paulus wil de gemeenten van de eerste reis opnieuw bezoeken, nu met Silas. In Lystra komt Timotheüs erbij. De Heilige Geest laat hen niet in Asia en Bithynië prediken. In Troas ziet Paulus ’s nachts in een gezicht een Macedonische man die smeekt: ‘Kom over in Macedonië, en help ons.’ Ze varen over naar Neapolis en gaan naar Filippi. Daar opent de Heere bij de rivier het hart van Lydia, een purperverkoopster; ze wordt met haar huis gedoopt. Paulus drijft een waarzeggende geest uit een slavin. Daarom worden Paulus en Silas gegeseld en in het blok gezet. Om middernacht zingen ze lofzangen. Dan komt er een aardbeving, en alle deuren gaan open. De gevangenbewaarder vraagt: ‘wat moet ik doen, opdat ik zalig worde?’ Ze antwoorden: ‘Geloof in den Heere Jezus Christus, en gij zult zalig worden, gij en uw huis.’ Hij wordt die nacht nog gedoopt. Hij is blij dat hij met zijn hele huis tot geloof gekomen is.",
  betekenis: "Paulus gaat niet zomaar ergens heen: de Heilige Geest stuurt hem, en hij besluit ‘dat ons de Heere geroepen had, om denzelven het Evangelie te verkondigen’ (Handelingen 16:10). Paulus schrijft later: ‘hoe zullen zij prediken, indien zij niet gezonden worden?’ (Romeinen 10:15).",
  wie: ["Paulus", "Silas", "Timotheüs", "Lydia", "Gevangenbewaarder"], kw: "zending",
  ontdek: { soort: "kaart", titel: "Een gezicht in de nacht", vraag: "Tik op Troas, de havenstad waar Paulus de Macedonische man zag.", id: "nt_troas", v: [[36.0, 23.0], [42.0, 30.0]] },
  quiz: [{ q: "Wie nam Paulus mee op zijn tweede reis?", a: ["Silas", "Barnabas", "Johannes Markus"], why: "Handelingen 15:40" },
    { q: "Wat vroeg de Macedonische man in het gezicht?", a: ["Kom over in Macedonië, en help ons", "Blijf in Troas", "Ga terug naar Antiochië"], why: "Handelingen 16:9" },
    { q: "Wat verkocht Lydia?", a: ["Purper", "Olijfolie", "Vis"], why: "Handelingen 16:14" },
    { q: "Wat vroeg de gevangenbewaarder aan Paulus en Silas?", a: ["Wat moet ik doen, opdat ik zalig worde?", "Waarom zijt gij niet gevlucht?", "Wie heeft de deuren geopend?"], why: "Handelingen 16:30" }],
  cross: [["Romeinen 10:14–15", "‘Hoe zullen zij horen, zonder die hun predikt? En hoe zullen zij prediken, indien zij niet gezonden worden?’"],
    ["Mattheüs 28:19", "‘Gaat dan henen, onderwijst al de volken.’"],
    ["Filippenzen 1:3–5", "Paulus dankt God voor de gemeente in Filippi en hun gemeenschap aan het Evangelie ‘van den eersten dag af’."],
    ["Filippenzen 4:4", "‘Verblijdt u in den Heere te allen tijd.’ Dat schreef Paulus later aan deze gemeente."]],
  tl: [49, 50], tijd: "ca. 49–50 n.Chr.", tijdNoot: "Reconstructie: na de vergadering in Jeruzalem (Handelingen 15) en vóór het verblijf in Korinthe onder stadhouder Gallio (Handelingen 18:12; een inscriptie dateert Gallio ca. 51–52 n.Chr.). De Bijbel noemt geen jaartal.",
},
{
  nr: 146, t: "Paulus gevangen in Jeruzalem", ref: "Handelingen 21–23", sectie: "paulus",
  stappen: ["handelingen:nt-paulusrome:0", "handelingen:nt-paulusrome:1", "handelingen:nt-paulusrome:2"], vorm: "route",
  uitleg: "Paulus reist van Milete per schip naar Tyrus en vandaar naar Caesarea. In het huis van Filippus bindt de profeet Agabus zich met de gordel van Paulus: zo zullen de Joden in Jeruzalem hem binden. Iedereen smeekt hem niet te gaan. Maar Paulus is bereid om voor de Naam van de Heere Jezus te sterven. In Jeruzalem zien Joden uit Asia hem in de tempel. Ze roepen dat hij Grieken in de tempel heeft gebracht, en ze willen hem doodslaan. Romeinse soldaten redden hem, en op de trappen vertelt Paulus het volk hoe hij zich bekeerde. Voor de raad zegt hij dat hij geoordeeld wordt over de hoop en de opstanding van de doden. Dan krijgen de Farizeeën en de Sadduceeën onenigheid. ’s Nachts staat de Heere bij hem: zoals hij in Jeruzalem getuigd heeft, moet hij ook in Rome getuigen. Meer dan veertig mannen zweren hem te doden. De zoon van de zus van Paulus hoort het, en de overste stuurt Paulus ’s nachts met een grote groep soldaten naar Caesarea.",
  betekenis: "Paulus wist dat banden en verdrukkingen hem wachtten, maar zei: ‘ik acht op geen ding, noch houde mijn leven dierbaar voor mijzelven’ (Handelingen 20:24). De Heere had al bij zijn roeping gezegd: ‘Ik zal hem tonen, hoeveel hij lijden moet om Mijn Naam’ (Handelingen 9:16).",
  wie: ["Paulus", "Agabus", "Filippus de evangelist", "Overste", "Neef"],
  ontdek: { soort: "wiezei", titel: "Wie zei het?", items: [
    ["Dit zegt de Heilige Geest: Den man, wiens deze gordel is, zullen de Joden alzo te Jeruzalem binden.", "Agabus", ["Filippus", "Jakobus"]],
    ["De wil des Heeren geschiede.", "De vrienden van Paulus in Caesarea", ["De overste", "De hogepriester"]],
    ["Ik heb dit burgerrecht voor een grote som gelds verkregen.", "De Romeinse overste", ["Paulus", "Felix"]],
    ["Heb goeden moed, Paulus.", "De Heere, in de nacht", ["De neef van Paulus", "Agabus"]]] },
  quiz: [{ q: "Hoeveel dochters had Filippus de evangelist, die profeteerden?", a: ["Vier", "Twee", "Zeven"], why: "Handelingen 21:9" },
    { q: "Met wie hadden de Joden Paulus eerder in de stad gezien?", a: ["Met Trofimus, den Efeziër", "Met Barnabas", "Met Cornelius"], why: "Handelingen 21:29" },
    { q: "Wat zei Paulus over zijn burgerrecht?", a: ["Ik ben een burger geboren", "Ik heb het gekocht", "Ik heb het niet"], why: "Handelingen 22:28" },
    { q: "Hoeveel mannen hadden gezworen Paulus te doden?", a: ["Meer dan veertig", "Twaalf", "Zeven"], why: "Handelingen 23:13" }],
  cross: [["Handelingen 20:22–24", "Paulus reist ‘gebonden zijnde door den Geest’ naar Jeruzalem, niet wetend wat hem daar zal ontmoeten."],
    ["Handelingen 9:15–16", "De Heere noemde Paulus een uitverkoren vat, en zei hoeveel hij om Zijn Naam zou moeten lijden."],
    ["Filippenzen 3:5", "Paulus noemt zich ‘een Hebreër uit de Hebreën, naar de wet een Farizeër’."]],
  tl: [57, 57], tijd: "ca. 57 n.Chr.", tijdNoot: "Reconstructie: twee jaar vóór de komst van Festus (Handelingen 24:27), die meestal rond 59 n.Chr. wordt gedateerd. Andere dateringen liggen tussen ca. 55 en 58 n.Chr.",
},
{
  nr: 147, t: "Een ramp op zee", ref: "Handelingen 25:1–12; 27", sectie: "paulus",
  stappen: ["handelingen:nt-paulusrome:3", "handelingen:nt-paulusrome:4", "handelingen:nt-paulusrome:5"], vorm: "route",
  uitleg: "Na twee jaar gevangenschap in Caesarea staat Paulus voor de nieuwe stadhouder Festus. De Joden willen dat hij naar Jeruzalem komt. Maar Paulus zegt: ‘Ik beroep mij op den keizer’, en Festus antwoordt: ‘Gij zult tot den keizer gaan.’ Met andere gevangenen gaat hij onder de hoede van de hoofdman Julius aan boord. Langs Sidon, Cyprus en Myra komen ze in Schone Havens op Kreta. Paulus waarschuwt dat de reis grote schade zal geven, maar ze varen toch verder. Een stormwind grijpt het schip. Dagenlang zien ze zon noch sterren, en ze gooien de lading en het scheepsgereedschap overboord. Dan zegt Paulus dat een engel van God hem heeft verzekerd dat niemand zijn leven zal verliezen, alleen het schip. In de veertiende nacht naderen ze land. Paulus laat iedereen eten en dankt God. Het schip loopt vast op een plek met aan twee kanten zee, en het achterschip breekt. Toch komen alle 276 opvarenden zwemmend of op planken behouden aan land.",
  betekenis: "Midden in de storm vertrouwt Paulus op Gods woord: ‘ik geloof Gode, dat het alzo zijn zal, gelijkerwijs het mij gezegd is’ (Handelingen 27:25). God doet wat Hij beloofd heeft: ‘zij allen behouden aan het land gekomen zijn’ (27:44).",
  wie: ["Paulus", "Festus", "Julius", "Aristarchus", "Bemanning"],
  ontdek: { soort: "volgorde", titel: "Zet de zeereis op volgorde", items: [
    "Caesarea", "Sidon", "Myra in Lycië", "Knidus", "Schone Havens op Kreta", "Klauda", "Schipbreuk bij een eiland"] },
  quiz: [{ q: "Wie werd na Felix stadhouder?", a: ["Porcius Festus", "Claudius Lysias", "Pontius Pilatus"], why: "Handelingen 24:27" },
    { q: "Hoe heette de stormwind die tegen het schip sloeg?", a: ["Euroklydon", "Sirocco", "Boreas"], why: "Handelingen 27:14" },
    { q: "Wie stond in de nacht bij Paulus en zei: ‘Vrees niet’?", a: ["Een engel Gods", "De hoofdman Julius", "De stuurman"], why: "Handelingen 27:23–24" },
    { q: "Hoeveel ankers wierpen ze uit het achterschip?", a: ["Vier", "Twee", "Zeven"], why: "Handelingen 27:29" }],
  cross: [["Psalm 107:28–30", "‘Hij doet den storm stilstaan, zodat hun golven stilzwijgen … en dat Hij hen tot de haven hunner begeerte geleid heeft.’"],
    ["Jona 1:4", "Ook in het verhaal van Jona stuurt de HEERE een grote storm op zee."],
    ["Markus 4:39", "De Heere Jezus zei tegen de zee: ‘Zwijg, wees stil!’"],
    ["2 Korinthe 11:25", "‘Driemaal heb ik schipbreuk geleden.’"]],
  tl: [59, 60], tijd: "ca. 59–60 n.Chr.", tijdNoot: "Reconstructie: Festus komt meestal rond 59 n.Chr. in het land; de zeereis begint na ‘de vasten’ (Handelingen 27:9), in de herfst. Andere dateringen liggen een paar jaar eerder.",
},
{
  nr: 148, t: "Paulus in Rome", ref: "Handelingen 28", sectie: "paulus",
  stappen: ["handelingen:nt-paulusrome:6", "handelingen:nt-paulusrome:7", "handelingen:nt-paulusrome:8"], vorm: "route",
  uitleg: "Na de schipbreuk blijken ze op het eiland Melite (Malta) te zijn. De bewoners maken een groot vuur. Als Paulus takken op het vuur legt, bijt een adder zich vast aan zijn hand. De mensen denken dat hij een moordenaar is. Maar hij schudt het beest in het vuur en merkt niets, en dan zeggen ze dat hij een god is. Publius, de voornaamste van het eiland, ontvangt hen. Paulus geneest zijn vader, en daarna worden ook andere zieken genezen. Na drie maanden varen ze verder, via Syracuse en Regium naar Puteoli, en dan gaat het over land naar Rome. Broeders uit Rome komen hen tegemoet, en Paulus dankt God en grijpt moed. In Rome mag hij met een soldaat in een eigen huis wonen. Twee hele jaren ontvangt hij iedereen die bij hem komt. Hij predikt het Koninkrijk van God en leert over de Heere Jezus Christus, met alle vrijmoedigheid en onverhinderd.",
  betekenis: "De Heere had gezegd dat Paulus ook in Rome zou getuigen (Handelingen 23:11), en zo gebeurt het. Het boek Handelingen eindigt niet met Paulus, maar met het Evangelie dat ‘onverhinderd’ gepredikt wordt (Handelingen 28:31).",
  wie: ["Paulus", "Publius", "Broeders"],
  ontdek: { soort: "koppel", titel: "Wie of wat hoort bij elkaar?", paren: [
    ["Melite", "het eiland waar het schip strandde (28:1)"],
    ["Publius", "de voornaamste van het eiland, die hen drie dagen ontving (28:7)"],
    ["Kastor en Pollux", "het teken van het schip uit Alexandrië (28:11)"],
    ["Puteoli", "hier vonden ze broeders en bleven ze zeven dagen (28:13–14)"],
    ["Forum van Appius", "tot hier kwamen broeders uit Rome hen tegemoet (28:15)"]] },
  quiz: [{ q: "Waarom staken de bewoners van Malta een vuur aan?", a: ["Om de regen en de koude", "Om een offer te brengen", "Om schepen te waarschuwen"], why: "Handelingen 28:2" },
    { q: "Wat zeiden de bewoners toen Paulus geen last had van de adder?", a: ["Dat hij een god was", "Dat hij een tovenaar was", "Dat het beest niet giftig was"], why: "Handelingen 28:6" },
    { q: "Hoeveel maanden bleven ze op het eiland?", a: ["Drie", "Zes", "Twaalf"], why: "Handelingen 28:11" },
    { q: "Hoe predikte Paulus in Rome het Koninkrijk Gods?", a: ["Met alle vrijmoedigheid, onverhinderd", "Alleen in het geheim", "Alleen in de synagoge"], why: "Handelingen 28:31" }],
  cross: [["Handelingen 23:11", "‘Alzo moet gij ook te Rome getuigen.’"],
    ["Markus 16:18", "‘Slangen zullen zij opnemen … dat zal hun niet schaden.’"],
    ["Romeinen 1:15", "Paulus had al eerder geschreven dat hij graag ‘die te Rome zijt’ het Evangelie wilde verkondigen."],
    ["Filippenzen 1:12–13", "Zijn gevangenschap kwam ‘meer tot bevordering van het Evangelie’."]],
  tl: [60, 62], tijd: "ca. 60–62 n.Chr.", tijdNoot: "Reconstructie: na de winter op Malta komt Paulus in Rome en blijft daar twee hele jaren (Handelingen 28:11, 30). Met de gangbare datering van Festus (ca. 59) geeft dat ongeveer 60–62 n.Chr.",
},
{
  nr: 149, t: "Johannes op Patmos", ref: "Openbaring 1–20", sectie: "openbaring",
  stappen: ["openbaring:nt-openbaring:0", "openbaring:nt-openbaring:1", "openbaring:nt-openbaring:2", "openbaring:nt-openbaring:3", "openbaring:nt-openbaring:4", "openbaring:nt-openbaring:5", "openbaring:nt-openbaring:6", "openbaring:nt-openbaring:7"], vorm: "symbool",
  uitleg: "Johannes is op het eiland Patmos, om het Woord van God en de getuigenis van Jezus Christus. Op de dag des Heeren hoort hij een stem als een bazuin. Die zegt dat hij moet opschrijven wat hij ziet, voor zeven gemeenten in Asia. Hij ziet de Zoon des mensen tussen zeven gouden kandelaren, met zeven sterren in Zijn rechterhand. Johannes valt als dood neer, maar hoort: ‘Vrees niet; Ik ben de Eerste en de Laatste.’ Elke gemeente krijgt een brief, met wat goed is, wat niet goed is, en een belofte voor wie overwint. Daarna ziet Johannes een deur open in de hemel, en een troon met Iemand erop, omringd door vierentwintig ouderlingen. Niemand kan het boek met de zeven zegels openen, behalve het Lam. Het Lam is geslacht en heeft met Zijn bloed mensen uit alle volken voor God gekocht. Johannes ziet ook oordelen over de aarde, en de strijd van de draak, de oude slang, die uit de hemel geworpen wordt. Aan het eind ziet hij een grote witte troon. Daar worden de doden geoordeeld naar hun werken, en het boek des levens wordt geopend.",
  betekenis: "Openbaring is ‘de openbaring van Jezus Christus, die God hem gegeven heeft’ (Openbaring 1:1). Het boek laat zien dat het Lam overwint en dat God het oordeel in handen heeft (Openbaring 5:5; 20:11–12). Bij de beelden geldt: de betekenis die de Bijbel zelf geeft, is de vaste grond.",
  wie: ["Johannes"], kw: "openbaring",
  ontdek: { soort: "symbolen", titel: "Wat betekent het? De Bijbel legt het zelf uit", items: [
    ["Zeven sterren", "de engelen van de zeven gemeenten", "Openbaring 1:20"],
    ["Zeven gouden kandelaren", "de zeven gemeenten", "Openbaring 1:20"],
    ["Zeven vurige lampen voor de troon", "de zeven geesten Gods", "Openbaring 4:5"],
    ["De Leeuw uit de stam van Juda", "de Wortel Davids, Die overwonnen heeft om het boek te openen", "Openbaring 5:5"],
    ["Gouden fiolen vol reukwerk", "de gebeden der heiligen", "Openbaring 5:8"],
    ["De grote draak", "de oude slang, die genaamd wordt duivel en satanas", "Openbaring 12:9"],
    ["De wateren waar de vrouw op zit", "volken, scharen, naties en tongen", "Openbaring 17:15"],
    ["Rein en blinkend fijn lijnwaad", "de rechtvaardigmakingen der heiligen", "Openbaring 19:8"]] },
  quiz: [{ q: "Hoe klonk de stem die Johannes achter zich hoorde?", a: ["Als een bazuin", "Als een fluistering", "Als een donderslag"], why: "Openbaring 1:10" },
    { q: "Wie kon het boek met de zeven zegels openen?", a: ["De Leeuw uit de stam van Juda, het Lam", "Een sterke engel", "Johannes"], why: "Openbaring 5:5–6" },
    { q: "Hoeveel ouderlingen zaten rondom de troon?", a: ["Vierentwintig", "Twaalf", "Zeventig"], why: "Openbaring 4:4" },
    { q: "Hoe wordt de grote draak ook genoemd?", a: ["De oude slang, de duivel en satanas", "De Leeuw uit Juda", "De morgenster"], why: "Openbaring 12:9" },
    { q: "Wat werd er bij de grote witte troon geopend?", a: ["De boeken en het boek des levens", "De zeven zegels", "De poorten van de stad"], why: "Openbaring 20:12" }],
  cross: [["Daniël 7:13", "Daniël zag ‘Een met de wolken des hemels, als eens mensen zoon’."],
    ["Genesis 49:9", "Jakob noemt Juda ‘een leeuwenwelp’. In Openbaring 5:5 is de Leeuw uit de stam van Juda de Wortel Davids."],
    ["Johannes 1:29", "Johannes de Doper wees op Jezus: ‘Zie het Lam Gods, Dat de zonde der wereld wegneemt!’"],
    ["Genesis 3:15", "God zei tegen de slang dat het zaad van de vrouw hem de kop zou vermorzelen. In Openbaring 12:9 wordt de draak ‘de oude slang’ genoemd."]],
  tl: [95, 95], tijd: "ca. 95 n.Chr.", tijdNoot: "Reconstructie; de Bijbel noemt geen jaartal. Irenaeus (ca. 180 n.Chr.) schrijft dat Johannes de Openbaring zag aan het einde van de regering van keizer Domitianus (81–96 n.Chr.). Sommige uitleggers dateren het boek rond 68 n.Chr.",
},
{
  nr: 150, t: "Alle dingen nieuw", ref: "Jesaja 11 en Openbaring 21–22", sectie: "openbaring",
  stappen: ["openbaring:nt-openbaring:0"], vorm: "thema",
  uitleg: "Jesaja profeteert dat er een Rijsje zal voortkomen uit de afgehouwen tronk van Isaï. De Geest van de HEERE zal op Hem rusten, en Hij zal de armen met gerechtigheid richten. In Zijn rijk zal de wolf bij het lam wonen, en een klein kind zal ze leiden. Men zal nergens leed doen, want de aarde zal vol zijn van de kennis van de HEERE. Eeuwen later ziet Johannes een nieuwe hemel en een nieuwe aarde, en het nieuwe Jeruzalem, dat van God uit de hemel neerdaalt. Een stem zegt: ‘de tabernakel Gods is bij de mensen.’ God zal alle tranen afwissen, en de dood, rouw, geroep en moeite zullen er niet meer zijn. ‘Ziet, Ik maak alle dingen nieuw.’ De stad heeft twaalf poorten van parels en geen tempel, want de Heere God en het Lam zijn haar Tempel. Er is geen nacht. Aan beide kanten van de rivier van het water des levens staat de boom des levens, en er zal geen vervloeking meer zijn. Wie onrein is of de leugen liefheeft, komt er niet in; alleen wie geschreven staan in het boek des levens van het Lam. Het laatste gebed van de Bijbel is: ‘Ja, kom, Heere Jezus!’",
  betekenis: "Wat in het paradijs verloren ging, laat God aan het einde in volle heerlijkheid terugzien: de boom des levens en geen vervloeking meer (Genesis 3:17, 24; Openbaring 22:2–3). De Heere Jezus zegt: ‘Ik ben de Wortel en het geslacht Davids’ (Openbaring 22:16): Hij is het Rijsje uit de tronk van Isaï.",
  wie: ["Johannes", "Jesaja"],
  ontdek: { soort: "verbanden", titel: "Van Jesaja en Genesis naar Openbaring", items: [
    ["Jesaja 11:1", "Er zal een Rijsje voortkomen uit de afgehouwen tronk van Isaï.", "Openbaring 22:16", "‘Ik, Jezus … Ik ben de Wortel en het geslacht Davids.’"],
    ["Jesaja 11:9", "Men zal nergens leed doen noch verderven op Gods heilige berg.", "Openbaring 21:4", "De dood zal niet meer zijn, noch rouw, noch gekrijt, noch moeite."],
    ["Jesaja 65:17", "‘Ik schep nieuwe hemelen en een nieuwe aarde.’", "Openbaring 21:1", "Johannes ziet een nieuwe hemel en een nieuwe aarde."],
    ["Genesis 3:24", "De weg naar de boom des levens wordt bewaakt door cherubs.", "Openbaring 22:2", "De boom des levens staat aan beide kanten van de rivier."],
    ["Genesis 3:17", "Het aardrijk is vervloekt om de zonde van Adam.", "Openbaring 22:3", "‘Geen vervloeking zal er meer tegen iemand zijn.’"]] },
  quiz: [{ q: "Uit wiens afgehouwen tronk komt volgens Jesaja een Rijsje voort?", a: ["Uit de tronk van Isaï", "Uit de tronk van Saul", "Uit de tronk van Abraham"], why: "Jesaja 11:1" },
    { q: "Met welk dier zal volgens Jesaja de wolf verkeren?", a: ["Met het lam", "Met de leeuw", "Met de arend"], why: "Jesaja 11:6" },
    { q: "Waarvan was elke poort van het nieuwe Jeruzalem gemaakt?", a: ["Uit één parel", "Uit goud", "Uit jaspis"], why: "Openbaring 21:21" },
    { q: "Waarom zag Johannes geen tempel in de stad?", a: ["De Heere, de almachtige God, is haar Tempel, en het Lam", "De tempel was nog niet gebouwd", "Er woonde niemand in de stad"], why: "Openbaring 21:22" },
    { q: "Wat stond er aan beide zijden van de rivier van het water des levens?", a: ["De boom des levens", "Twaalf engelen", "Zeven kandelaren"], why: "Openbaring 22:2" }],
  cross: [["Jesaja 65:17", "‘Want ziet, Ik schep nieuwe hemelen en een nieuwe aarde.’"],
    ["Romeinen 15:12", "Paulus haalt Jesaja 11:10 aan: ‘Er zal zijn de wortel van Jessai … op Hem zullen de heidenen hopen.’"],
    ["Genesis 3:22–24", "Na de zondeval werd de weg naar de boom des levens afgesloten."],
    ["Mattheüs 3:16", "Bij de doop van de Heere Jezus daalde de Geest van God op Hem neer, zoals Jesaja 11:2 had gezegd."]],
  tl: [95, 95], tijd: "Jesaja: 8e eeuw v.Chr.; Openbaring: ca. 95 n.Chr.", tijdNoot: "Reconstructie. Jesaja profeteerde in de tijd van de koningen Uzzia tot Hizkia (Jesaja 1:1), ongeveer 740–700 v.Chr. Openbaring wordt meestal rond 95 n.Chr. gedateerd (sommigen: ca. 68 n.Chr.). Wat Openbaring 21–22 beschrijft, ligt in de toekomst; daarvoor geeft de Bijbel geen datum.",
}
);

BR.kernwoorden["heilige-geest"] = { n: "Heilige Geest",
  uitleg: "De Heilige Geest is God, samen met de Vader en de Zoon. Toen Ananias tegen de Heilige Geest loog, zei Petrus: ‘Gij hebt den mensen niet gelogen, maar Gode’ (Handelingen 5:3–4). De Heere Jezus beloofde Zijn discipelen een andere Trooster, de Geest der waarheid (Johannes 14:16–17), en met Pinksteren werd de Geest uitgestort. De Geest overtuigt van zonde, leidt in de waarheid, en niemand kan zeggen dat Jezus de Heere is, dan door de Heilige Geest (Johannes 16:8, 13; 1 Korinthe 12:3).",
  refs: [["Johannes 14:16–17", "De Heere Jezus belooft een andere Trooster, Die altijd bij de discipelen zal blijven."],
    ["Handelingen 2:4", "Met Pinksteren worden de discipelen allemaal vervuld met de Heilige Geest."],
    ["Handelingen 5:3–4", "Liegen tegen de Heilige Geest is liegen tegen God."],
    ["Galaten 5:22", "De vrucht van de Geest is liefde, blijdschap, vrede, lankmoedigheid, goedertierenheid, goedheid, geloof, zachtmoedigheid en matigheid."]] };
BR.kernwoorden.vergeving = { n: "Vergeving",
  uitleg: "Vergeven betekent: iemand zijn schuld niet meer aanrekenen. Bij God is vergeving van zonden door de Heere Jezus: ‘een iegelijk, die in Hem gelooft, vergeving der zonden ontvangen zal door Zijn Naam’ (Handelingen 10:43). ‘Indiën wij onze zonden belijden, Hij is getrouw en rechtvaardig, dat Hij ons de zonden vergeve’ (1 Johannes 1:9). Wie vergeving ontvangt, moet ook anderen vergeven, zoals de Heere Jezus leerde in het Onze Vader. Stefanus bad zelfs voor de mensen die hem stenigden (Handelingen 7:60).",
  refs: [["Psalm 32:1", "‘Welgelukzalig is hij, wiens overtreding vergeven, wiens zonde bedekt is.’"],
    ["Mattheüs 6:12", "‘En vergeef ons onze schulden, gelijk ook wij vergeven onzen schuldenaren.’"],
    ["Handelingen 10:43", "Ieder die in Christus gelooft, ontvangt vergeving van de zonden door Zijn Naam."],
    ["Efeze 4:32", "‘Vergevende elkander, gelijkerwijs ook God in Christus ulieden vergeven heeft.’"]] };
BR.kernwoorden.dienen = { n: "Dienen",
  uitleg: "Dienen is werken voor God en voor een ander, zonder jezelf groot te maken. De Heere Jezus zei dat Hij niet gekomen is om gediend te worden, maar om te dienen en Zijn leven te geven als losprijs voor velen (Markus 10:45). In de eerste gemeente werden zeven mannen gekozen om voor de weduwen te zorgen (Handelingen 6:1–6), en Tabitha was ‘vol van goede werken’ (Handelingen 9:36). Paulus schrijft: ‘dient elkander door de liefde’ (Galaten 5:13).",
  refs: [["Markus 10:45", "‘Want ook de Zoon des mensen is niet gekomen om gediend te worden, maar om te dienen.’"],
    ["Handelingen 6:2–3", "Zeven mannen worden gekozen voor het dagelijkse dienen van de tafels."],
    ["Galaten 5:13", "‘Dient elkander door de liefde.’"],
    ["1 Petrus 4:10", "Ieder moet de gave die hij gekregen heeft gebruiken om anderen te dienen."]] };
BR.kernwoorden.bekering = { n: "Bekering",
  uitleg: "Bekering betekent: omkeren. Wie zich bekeert, ziet zijn zonde, keert zich ervan af en wendt zich tot God. Petrus riep op: ‘Betert u dan, en bekeert u, opdat uw zonden mogen uitgewist worden’ (Handelingen 3:19). De Bijbel zegt ook dat God de bekering geeft (Handelingen 11:18), en dat er blijdschap in de hemel is over één zondaar die zich bekeert (Lukas 15:7). Saulus, de vervolger, is een voorbeeld van zo’n omkeer (Handelingen 9).",
  refs: [["Ezechiël 33:11", "‘Bekeert u, bekeert u van uw boze wegen, want waarom zoudt gij sterven?’"],
    ["Lukas 15:7", "Er is blijdschap in de hemel over één zondaar die zich bekeert."],
    ["Handelingen 3:19", "‘Betert u dan, en bekeert u, opdat uw zonden mogen uitgewist worden.’"],
    ["Handelingen 11:18", "‘Zo heeft dan God ook den heidenen de bekering gegeven ten leven!’"]] };
BR.kernwoorden.zending = { n: "Zending",
  uitleg: "Zending betekent: gezonden worden om het Evangelie te brengen aan wie het nog niet kent. Voor Zijn hemelvaart zei de Heere Jezus tegen Zijn discipelen dat ze Zijn getuigen zouden zijn, in Jeruzalem, Judea en Samaria en tot aan het uiterste der aarde (Handelingen 1:8). In Antiochië zei de Heilige Geest: ‘Zondert Mij af beiden Barnabas en Saulus’ (Handelingen 13:2). Paulus schrijft: ‘hoe zullen zij prediken, indien zij niet gezonden worden?’ (Romeinen 10:15).",
  refs: [["Mattheüs 28:19", "‘Gaat dan henen, onderwijst al de volken.’"],
    ["Handelingen 1:8", "‘Gij zult Mijn getuigen zijn … tot aan het uiterste der aarde.’"],
    ["Handelingen 13:2–3", "De gemeente in Antiochië zendt Barnabas en Saulus uit, na vasten en bidden."],
    ["Romeinen 10:14–15", "Mensen kunnen niet geloven zonder te horen, en niet horen zonder dat iemand gezonden wordt."]] };
BR.kernwoorden.openbaring = { n: "Openbaring",
  uitleg: "Openbaren betekent: bekendmaken wat verborgen was. Wij kunnen God niet uit onszelf leren kennen; God maakt Zichzelf bekend in Zijn Woord. ‘De verborgene dingen zijn voor den HEERE, onzen God; maar de geopenbaarde zijn voor ons en voor onze kinderen’ (Deuteronomium 29:29). God heeft vroeger gesproken door de profeten, en het laatst door Zijn Zoon (Hebreeën 1:1–2). Het laatste Bijbelboek heet Openbaring: ‘De openbaring van Jezus Christus, die God hem gegeven heeft’ (Openbaring 1:1).",
  refs: [["Deuteronomium 29:29", "De verborgen dingen zijn voor God; wat Hij bekendmaakt, is voor ons en onze kinderen."],
    ["Daniël 2:28", "‘Er is een God in den hemel, Die verborgenheden openbaart.’"],
    ["Hebreeën 1:1–2", "God heeft gesproken door de profeten, en in deze laatste dagen door de Zoon."],
    ["Openbaring 1:1", "Het boek Openbaring is de openbaring van Jezus Christus."]] };
